/**
 * Stage 1 cross-engine parity tests.
 *
 * These assert that the TypeScript engine produces EXACTLY the values listed
 * in `shared/fixtures/parity_expected.json`, which is generated by the Python
 * engine (`scripts/gen_parity_expected.py`). The Python suite asserts the
 * same file from the other side, so neither engine can drift from the other
 * without a test failure.
 *
 * Decisions: research-py/docs/STAGE1_PARITY_DECISIONS.md
 */
import * as fs from 'fs';
import * as path from 'path';

import { CSVLoader } from '../src/data/CSVLoader';
import { findSRZones } from '../src/indicators/supportResistance';
import { findFibRetracement } from '../src/indicators/fibonacci';
import { findTrendlines } from '../src/indicators/trendlines';
import { findSwingPoints } from '../src/indicators/swingPoints';
import { calculateATR } from '../src/indicators/atr';

const REPO_ROOT = path.resolve(__dirname, '..', '..');
const FIXTURE = path.join(REPO_ROOT, 'shared', 'fixtures', 'parity_15m.csv');
const EXPECTED = path.join(REPO_ROOT, 'shared', 'fixtures', 'parity_expected.json');

const SR_LOOKBACK = 100;
const FIB_LOOKBACK = 50;
const TRENDLINE_TOLERANCE_ATR = 0.3;

function loadExpected(): any {
  return JSON.parse(fs.readFileSync(EXPECTED, 'utf-8'));
}

const round = (n: number, places = 6): number => {
  const f = Math.pow(10, places);
  return Math.round(n * f) / f;
};

describe('Stage 1 parity: shared fixture expectations', () => {
  const expected = loadExpected();
  const candles = new CSVLoader().loadFromFile(FIXTURE);
  const atr = calculateATR(candles, 14);

  it('loads the same number of rows as the Python engine', () => {
    expect(candles.length).toBe(expected.row_count);
  });

  it('computes the same ATR (D1: Wilder smoothing)', () => {
    expect(round(atr, 10)).toBeCloseTo(expected.atr, 9);
  });

  it('finds the same swing highs (D2: already identical, must stay so)', () => {
    const swings = findSwingPoints(candles, 3, 3)
      .filter((s) => s.type === 'HIGH')
      .map((s) => [s.index, round(s.price)]);

    expect(swings).toEqual(expected.swing_highs);
  });

  it('finds the same swing lows (D2)', () => {
    const swings = findSwingPoints(candles, 3, 3)
      .filter((s) => s.type === 'LOW')
      .map((s) => [s.index, round(s.price)]);

    expect(swings).toEqual(expected.swing_lows);
  });

  it('finds the same S/R zones (D3)', () => {
    const zones = findSRZones(candles.slice(-SR_LOOKBACK), atr, 0.5, 2).map((z) => ({
      type: z.type,
      price_level: round(z.priceLevel),
      strength: z.strength,
    }));

    expect(zones).toEqual(expected.sr_zones);
  });

  it('finds the same Fibonacci retracement (D4)', () => {
    const fib = findFibRetracement(candles, FIB_LOOKBACK);

    if (expected.fib === null) {
      expect(fib).toBeNull();
      return;
    }

    expect(fib).not.toBeNull();
    expect(round(fib!.swingHigh)).toBeCloseTo(expected.fib.swing_high, 6);
    expect(round(fib!.swingLow)).toBeCloseTo(expected.fib.swing_low, 6);
    expect(fib!.direction).toBe(expected.fib.direction);

    const levels = fib!.levels.map((l) => ({
      ratio: round(l.ratio),
      price: round(l.price),
    }));
    expect(levels).toEqual(expected.fib.levels);
  });

  it('finds the same trendlines (D5: ATR-multiple tolerance)', () => {
    const trendlines = findTrendlines(candles, atr, TRENDLINE_TOLERANCE_ATR).map((t) => ({
      type: t.type,
      slope: round(t.slope, 10),
      intercept: round(t.intercept, 10),
      start_idx: t.startIndex,
      end_idx: t.endIndex,
      touches: t.touches,
    }));

    expect(trendlines.length).toBe(expected.trendlines.length);

    // Compare as sorted sets: the engines may enumerate candidates in a
    // different order, but the resulting set of trendlines must be identical.
    const key = (t: any) =>
      `${t.type}|${t.slope}|${t.intercept}|${t.start_idx}|${t.end_idx}|${t.touches}`;

    const pyKeys = expected.trendlines.map(key).sort();
    const tsKeys = trendlines.map(key).sort();

    expect(tsKeys).toEqual(pyKeys);
  });
});

describe('Stage 1 parity: determinism', () => {
  it('produces identical results on repeated runs', () => {
    const candles = new CSVLoader().loadFromFile(FIXTURE);
    const atr = calculateATR(candles, 14);

    const first = findSRZones(candles.slice(-100), atr, 0.5, 2)
      .map((z) => `${z.type}:${z.priceLevel}:${z.strength}`)
      .join('|');
    const second = findSRZones(candles.slice(-100), atr, 0.5, 2)
      .map((z) => `${z.type}:${z.priceLevel}:${z.strength}`)
      .join('|');

    expect(second).toBe(first);
  });
});
